//
// One 256-entry table per map, as concatenated six-digit hex.  These are
// seaborn's maps, baked to numbers so the page carries no dependency and
// colour() stays synchronous.  Which variable uses which lives in
// field.js, not here: this file is only the data.

const TABLES = {
  icefire:
    "",
  inferno:
    "",
  turbo:
    "",
  viridis:
    "",
};

const DECODED = new Map();

function decode(name) {
  if (!DECODED.has(name)) {
    const hex = TABLES[name];
    const bytes = new Uint8Array(256 * 3);
    for (let i = 0; i < 256 * 3; i++) {
      bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
    }
    DECODED.set(name, bytes);
  }
  return DECODED.get(name);
}

/** RGB in 0-255 for a normalized position, interpolated between entries. */
export function rampColour(name, t) {
  const bytes = decode(TABLES[name] ? name : "viridis");
  const x = Math.min(1, Math.max(0, t)) * 255;
  const i = Math.floor(x);
  const j = Math.min(255, i + 1);
  const f = x - i;
  return [
    bytes[i * 3] * (1 - f) + bytes[j * 3] * f,
    bytes[i * 3 + 1] * (1 - f) + bytes[j * 3 + 1] * f,
    bytes[i * 3 + 2] * (1 - f) + bytes[j * 3 + 2] * f,
  ];
}

export const RAMP_NAMES = Object.keys(TABLES);
